package com.turing.app.api.notification.controller;import com.turing.app.api.auth.security.AuthenticatedUser;import com.turing.app.api.notification.dto.NotificationDtos.NotificationResponse;import com.turing.app.api.notification.service.NotificationService;import java.util.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController public class NotificationController{private final NotificationService service;public NotificationController(NotificationService service){this.service=service;}@GetMapping("/api/me/notifications")public List<NotificationResponse> mine(@AuthenticationPrincipal AuthenticatedUser user){return service.mine(user.id());}@PatchMapping("/api/me/notifications/{id}/read")public NotificationResponse read(@AuthenticationPrincipal AuthenticatedUser user,@PathVariable UUID id){return service.read(user.id(),id);}}
